using System; using UnityEngine; using Mojinloop.InputActivity;
namespace Mojinloop.Gameplay { public sealed class InputActivityState:MonoBehaviour { [SerializeField,Min(.05f)] float activeHoldDuration=.5f; [SerializeField] GlobalInputActivityController input; public bool IsInputActive{get;private set;} public event Action<bool> Changed; float lastInputTime=float.NegativeInfinity; bool paused; public void Configure(GlobalInputActivityController i,float hold){input=i;activeHoldDuration=hold;} void OnEnable(){if(input!=null)input.ActivityDetected+=Pulse;} void OnDisable(){if(input!=null)input.ActivityDetected-=Pulse;} void Update(){bool next=!paused&&Time.unscaledTime-lastInputTime<=activeHoldDuration;if(next==IsInputActive)return;IsInputActive=next;Changed?.Invoke(next);} void Pulse(){if(!paused)lastInputTime=Time.unscaledTime;} public void SetPaused(bool value){paused=value;if(value){lastInputTime=float.NegativeInfinity;IsInputActive=false;Changed?.Invoke(false);}} } }
